import 'dart:math';

import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

import '../../models/screen_config.dart';
import '../../services/playback_controller.dart';
import '../../theme/app_palette.dart';
import '../../theme/app_typography.dart';
import 'base_hero_container.dart';
import 'hero_title_block.dart';

/// Dot visualisation embedded in the Void hero slot: a single pulsing circle
/// whose radius tracks the spectrum's bass energy (Void chrome owns
/// transport).
///
/// When [DotScreenConfig.showSongInfo] is true (B-020) the active track's
/// Artist (H1) / Song (H2) overlay the top of the band in a [Stack] above the
/// centered dot, using the shared [HeroTitleBlock] (B-046).
///
/// To prevent long metadata from intersecting the centered pulsing dot (at
/// normal and maximum hero text sizes), the dot's maximum radius is reduced
/// whenever the title overlay is enabled.
class DotHero extends StatelessWidget {
  const DotHero({super.key, required this.config});

  final DotScreenConfig config;

  double _bassFor(List<double> spectrum) {
    if (spectrum.isEmpty) return 0.0;
    var bass = 0.0;
    for (var i = 0; i < min(spectrum.length, 3); i++) {
      bass = max(bass, spectrum[i]);
    }
    return bass;
  }

  @override
  Widget build(BuildContext context) {
    final palette = Theme.of(context).extension<AppPalette>()!;
    // read (not watch): the dot animates off [spectrumListenable] below, so this
    // widget must NOT rebuild on every controller notify.
    final player = context.read<PlaybackController>();

    return LayoutBuilder(
      builder: (context, constraints) {
        final typography = Theme.of(context).extension<AppTypography>()!;

        // Dot stays centered, but its maximum radius may be reduced when the
        // title overlay is enabled so it can't intersect the text block.
        final maxAllowedByGeometry =
            min(constraints.maxWidth, constraints.maxHeight) / 2;
        final maxDotRadiusByText = config.showSongInfo
            ? (() {
                // HeroTitleBlock uses 1.18 line-height (see heroHeadingStyle).
                const lineHeightFactor = 1.18;
                final h1Size = typography.heroSize * config.textScale;
                final h2Size = h1Size * heroSongSizeFactor;

                // Worst-case: both artist and song occupy 2 lines.
                final artistHeightMax = 2 * h1Size * lineHeightFactor;
                final songHeightMax = 2 * h2Size * lineHeightFactor;
                const topPadding = 12.0;
                const artistToSongGap = 8.0;
                const safetyGap = 8.0;

                final reservedTitleBottom =
                    topPadding + artistHeightMax + artistToSongGap + songHeightMax;

                // Dot top is at (heroHeight/2 - r). Keep dotTop below the
                // reserved title bottom plus a small safety gap.
                final heroHalfHeight = constraints.maxHeight / 2;
                return (heroHalfHeight - reservedTitleBottom - safetyGap)
                    .clamp(0.0, double.infinity);
              })()
            : double.infinity;

        final dotMaxRadius =
            min(maxAllowedByGeometry, config.maxDotSize, maxDotRadiusByText);
        final dotMinRadius = min(config.minDotSize, dotMaxRadius);

        return BaseHeroContainer(
          child: Stack(
            children: [
              // Pulsing dot — always centered. Only this subtree repaints per
              // spectrum frame (RepaintBoundary-isolated).
              Center(
                child: RepaintBoundary(
                  child: AnimatedBuilder(
                    animation: player.spectrumListenable,
                    builder: (context, _) {
                      final bass = _bassFor(player.spectrumData);
                      final raw = config.minDotSize +
                          bass * bass * config.sensitivity *
                              (config.maxDotSize - config.minDotSize);
                      final r = raw.clamp(dotMinRadius, dotMaxRadius);
                      return Container(
                        width: r * 2,
                        height: r * 2,
                        decoration: BoxDecoration(
                          color: palette.fgPrimary
                              .withValues(alpha: config.dotOpacity),
                          shape: BoxShape.circle,
                        ),
                      );
                    },
                  ),
                ),
              ),
              // Optional song-info overlay pinned to the top of the hero band
              // (B-020), above the dot.
              if (config.showSongInfo)
                Positioned(
                  left: 0,
                  right: 0,
                  top: 12,
                  child: Opacity(
                    opacity: config.textOpacity.clamp(0.0, 1.0),
                    child: HeroTitleBlock(textScale: config.textScale),
                  ),
                ),
            ],
          ),
        );
      },
    );
  }
}

